a {
  text-decoration-line: underline; /* Ensure underline is active */
  text-decoration-color: var(--link-color, #007bff);
  text-decoration-thickness: 0.08em; /* Adjust thickness relative to font size */
  text-underline-offset: 0.2em; /* Lift the underline up */
}

a:hover {
  text-decoration-thickness: 0.12em; /* Slightly thicker on hover */
  text-underline-offset: 0.18em; /* Adjust offset slightly if desired */
}
